// Extraer chat_id, texto del paciente y nombre
const item = $input.first().json;
let chat_id = null;
let text = '';
let user_name = '';

if (item.message) {
  chat_id = String(item.message.chat.id);
  text = item.message.text || '';
  user_name = item.message.from.first_name || 'Paciente';
} else if (item.callback_query) {
  chat_id = String(item.callback_query.message.chat.id);
  text = item.callback_query.data || '';
  user_name = item.callback_query.from.first_name || 'Paciente';
}

const hoy = new Date();
const dias = ['Domingo', 'Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado'];
const meses = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
const yyyy = hoy.getFullYear();
const mm = String(hoy.getMonth() + 1).padStart(2, '0');
const dd = String(hoy.getDate()).padStart(2, '0');
const fechaIsoHoy = `${yyyy}-${mm}-${dd}`;
const fechaTextoHoy = `${dias[hoy.getDay()]} ${hoy.getDate()} de ${meses[hoy.getMonth()]} de ${yyyy}`;

return [{
  json: {
    chat_id,
    text,
    user_name,
    sessionId: chat_id,
    fecha_actual_iso: fechaIsoHoy,
    fecha_actual_texto: fechaTextoHoy
  }
}];

let input = {};
if (typeof query === 'object' && query !== null) {
  input = query;
} else if (typeof query === 'string') {
  try {
    input = JSON.parse(query);
  } catch (e) {
    input = { raw: query };
  }
}
const rawStr = JSON.stringify(input).toLowerCase();

const dias = ['Domingo', 'Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado'];
const meses = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];

function formatFechaEsp(d) {
  return dias[d.getDay()] + ' ' + d.getDate() + ' de ' + meses[d.getMonth()] + ' de ' + d.getFullYear();
}

function toIsoDate(d) {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return y + '-' + m + '-' + day;
}

const hoy = new Date();
hoy.setHours(0, 0, 0, 0);

let targetDate = null;
let fechaStr = input.fecha || '';

// Si vino una fecha en formato YYYY-MM-DD
if (!fechaStr) {
  const m = rawStr.match(/202[0-9]-[0-1][0-9]-[0-3][0-9]/);
  if (m) fechaStr = m[0];
}

// Corregir si el modelo pasó un año antiguo como 2023 o 2024
if (fechaStr) {
  const parts = fechaStr.split('-');
  if (parts.length === 3) {
    let y = parseInt(parts[0]);
    if (y < hoy.getFullYear()) y = hoy.getFullYear();
    targetDate = new Date(y, parseInt(parts[1]) - 1, parseInt(parts[2]));
    targetDate.setHours(0, 0, 0, 0);
    fechaStr = toIsoDate(targetDate);
  }
}

// Detección inteligente de días de la semana relativos si no se calculó fecha
if (!targetDate) {
  const mapaDias = { 'lunes': 1, 'martes': 2, 'miercoles': 3, 'miércoles': 3, 'jueves': 4, 'viernes': 5 };
  for (const [nom, diaNum] of Object.entries(mapaDias)) {
    if (rawStr.includes(nom)) {
      let d = new Date(hoy);
      do {
        d.setDate(d.getDate() + 1);
      } while (d.getDay() !== diaNum);
      targetDate = d;
      fechaStr = toIsoDate(d);
      break;
    }
  }
}

// SI HAY UNA FECHA SOLICITADA (ESPECÍFICA O RELATIVA)
if (targetDate) {
  // 1. Validar que no sea pasada
  if (targetDate < hoy) {
    return JSON.stringify({
      disponible: false,
      error: 'FECHA_PASADA',
      motivo: 'La fecha ' + formatFechaEsp(targetDate) + ' ya ha pasado. Por favor elige una fecha futura.'
    });
  }

  // 2. Validar que no sea fin de semana
  const dw = targetDate.getDay();
  if (dw === 0 || dw === 6) {
    return JSON.stringify({
      disponible: false,
      error: 'FIN_DE_SEMANA',
      motivo: 'La clínica dental abre exclusivamente de lunes a viernes. El ' + formatFechaEsp(targetDate) + ' es fin de semana. Por favor selecciona un día de lunes a viernes.'
    });
  }

  // 3. ¡FECHA HÁBIL FUTURA VÁLIDA!
  let turnos = ['10:30', '12:00', '16:30', '17:30'];
  if (rawStr.includes('15:00') || (input.hora && input.hora.includes('15:00'))) {
    turnos = ['15:45', '16:30', '17:15', '18:00'];
  }

  return JSON.stringify({
    disponible: true,
    fecha_solicitada_iso: fechaStr,
    dia_solicitado: formatFechaEsp(targetDate),
    turnos_disponibles: turnos,
    mensaje: 'Hay disponibilidad completa para el ' + formatFechaEsp(targetDate) + '. Ofrécele al paciente estos horarios disponibles (' + turnos.join(', ') + ').'
  });
}

// SI EL PACIENTE NO ESPECIFICÓ FECHA (consulta general de huecos más cercanos)
const diasHabiles = [];
let cursor = new Date(hoy);
while (diasHabiles.length < 4) {
  cursor.setDate(cursor.getDate() + 1);
  const dw = cursor.getDay();
  if (dw !== 0 && dw !== 6) {
    diasHabiles.push({
      fecha_iso: toIsoDate(cursor),
      nombre_dia: formatFechaEsp(cursor),
      turnos_disponibles: ['10:30', '12:00', '16:30', '17:30']
    });
  }
}

return JSON.stringify({
  disponible: true,
  mensaje: 'El paciente puede agendar para cualquier fecha futura de lunes a viernes. Sugerencias más cercanas:',
  proximas_fechas_sugeridas: diasHabiles
});

