const https = require('https');
const HOST = 'ibnkmbcnkrvwdtrjmcel.supabase.co';
const SERVICE_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImlibmttYmNua3J2d2R0cmptY2VsIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc4OTExNDc4MCwiZXhwIjoyMTA0NjkwNzgwfQ.DwRIy8-ktRewOdswssnA-oC_b4TVLa0jSrLmjkXIS40';

const baseHeaders = {
  'apikey': SERVICE_KEY,
  'Authorization': 'Bearer ' + SERVICE_KEY,
  'Content-Type': 'application/json',
  'Prefer': 'return=representation'
};

function getSupabase(reqPath) {
  return new Promise((resolve, reject) => {
    const req = https.request({
      hostname: HOST,
      port: 443,
      path: reqPath,
      method: 'GET',
      headers: baseHeaders
    }, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try { resolve(JSON.parse(data)); } catch (e) { resolve(data); }
      });
    });
    req.on('error', reject);
    req.end();
  });
}

function postSupabase(reqPath, body) {
  return new Promise((resolve, reject) => {
    const postData = typeof body === 'string' ? body : JSON.stringify(body);
    const req = https.request({
      hostname: HOST,
      port: 443,
      path: reqPath,
      method: 'POST',
      headers: baseHeaders
    }, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try { resolve(JSON.parse(data)); } catch (e) { resolve(data); }
      });
    });
    req.on('error', reject);
    req.write(postData);
    req.end();
  });
}

function patchSupabase(reqPath, body) {
  return new Promise((resolve, reject) => {
    const postData = typeof body === 'string' ? body : JSON.stringify(body);
    const req = https.request({
      hostname: HOST,
      port: 443,
      path: reqPath,
      method: 'PATCH',
      headers: baseHeaders
    }, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try { resolve(JSON.parse(data)); } catch (e) { resolve(data); }
      });
    });
    req.on('error', reject);
    req.write(postData);
    req.end();
  });
}

function toIsoDate(d) {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return y + '-' + m + '-' + day;
}

function getNextBusinessDayIso() {
  let d = new Date();
  do {
    d.setDate(d.getDate() + 1);
  } while (d.getDay() === 0 || d.getDay() === 6);
  return toIsoDate(d);
}

let dni = (input.dni || input.DNI || '').toString().replace(/[^0-9A-Z]/gi, '').trim();
let nombreCompleto = (input.nombre || input.nombre_completo || input.paciente || '').toString().trim();
let telefono = (input.telefono || input.celular || '').toString().trim();
let especialidad = (input.especialidad || 'General').toString().trim();
let fecha = (input.fecha || '').toString().trim();
let hora = (input.hora || '').toString().trim();

const rawStr = JSON.stringify(input);
if (!fecha) {
  const mFecha = rawStr.match(/202[0-9]-[0-1][0-9]-[0-3][0-9]/);
  if (mFecha) {
    fecha = mFecha[0];
  } else {
    fecha = getNextBusinessDayIso();
  }
}

if (!hora) {
  const mHora = rawStr.match(/([0-2]?[0-9]:[0-5][0-9])/);
  if (mHora) {
    hora = mHora[1];
  } else {
    hora = '10:30';
  }
}

if (!dni && input.datos_crudos) {
  const mDni = input.datos_crudos.match(/([0-9]{7,8}[A-Z]|[XYZ][0-9]{7}[A-Z]|[0-9]{8})/i);
  if (mDni) dni = mDni[0].toUpperCase();
}

try {
  let pacienteId = null;

  if (dni) {
    const pData = await getSupabase('/rest/v1/clinica_pacientes?dni=eq.' + dni + '&select=id,nombre,apellidos');
    if (Array.isArray(pData) && pData.length > 0) {
      pacienteId = pData[0].id;
    }
  }

  if (!pacienteId) {
    const partes = nombreCompleto ? nombreCompleto.split(' ') : ['Paciente'];
    const nuevoPaciente = {
      dni: dni || ('DNI-' + Math.floor(10000000 + Math.random() * 90000000)),
      nombre: partes[0] || 'Paciente',
      apellidos: partes.slice(1).join(' ') || '',
      telefono: telefono || '600000000',
      acepta_rgpd: true,
      fecha_alta: new Date().toISOString()
    };

    const insData = await postSupabase('/rest/v1/clinica_pacientes', nuevoPaciente);
    if (Array.isArray(insData) && insData.length > 0) {
      pacienteId = insData[0].id;
    }
  }

  const doctores = await getSupabase('/rest/v1/clinica_doctores?select=*');
  let doctorAsignado = (Array.isArray(doctores) && doctores.length > 0) ? doctores[0] : { id: null, consultorio_asignado: 1, nombre_completo: 'Dra. Martínez', especialidad: 'General' };

  if (Array.isArray(doctores)) {
    const espNorm = especialidad.toLowerCase();
    const found = doctores.find(d => (d.especialidad || '').toLowerCase().includes(espNorm));
    if (found) doctorAsignado = found;
  }

  const fechaLimpia = fecha.replace(/[^0-9-]/g, '') || getNextBusinessDayIso();
  const horaLimpia = hora.length === 5 ? (hora + ':00') : (hora.length === 8 ? hora : '10:30:00');
  const startIso = fechaLimpia + 'T' + horaLimpia + 'Z';

  const espFinal = doctorAsignado.especialidad || especialidad;

  // Duración según especialidad (media hora / 30 minutos por defecto para todos los turnos, configurable)
  const duracionesMinutos = {
    'general': 30,
    'odontología general': 30,
    'limpieza': 30,
    'ortodoncia': 30,
    'estética dental': 30,
    'blanqueamiento': 30,
    'revisión': 30,
    'periodoncia': 45,
    'prótesis': 45,
    'endodoncia': 45,
    'cirugía': 60,
    'implante': 60,
    'implantología': 60
  };

  let duracionMin = 30; // 30 minutos por defecto
  const espKey = (espFinal || '').toLowerCase();
  for (const [k, v] of Object.entries(duracionesMinutos)) {
    if (espKey.includes(k)) {
      duracionMin = v;
      break;
    }
  }

  const startDate = new Date(startIso);
  const endDate = new Date(startDate.getTime() + duracionMin * 60 * 1000);
  const endIso = endDate.toISOString();

  // Reprogramación automática si ya tiene una cita activa para la misma especialidad
  const prevCitas = await getSupabase('/rest/v1/clinica_citas?paciente_id=eq.' + pacienteId + '&especialidad=eq.' + encodeURIComponent(espFinal) + '&estado=eq.PROGRAMADA&select=*');

  let citaCode = '';
  if (Array.isArray(prevCitas) && prevCitas.length > 0) {
    const cExist = prevCitas[0];
    citaCode = cExist.erp_cita_id || ('NEC-' + Math.floor(1000 + Math.random() * 9000));
    await patchSupabase('/rest/v1/clinica_citas?id=eq.' + cExist.id, {
      doctor_id: doctorAsignado.id,
      consultorio_num: doctorAsignado.consultorio_asignado || 1,
      fecha_hora_inicio: startIso,
      fecha_hora_fin: endIso,
      canal_origen: 'TELEGRAM',
      fecha_actualizacion: new Date().toISOString()
    });
  } else {
    citaCode = 'NEC-' + Math.floor(1000 + Math.random() * 9000);
    const nuevaCita = {
      erp_cita_id: citaCode,
      paciente_id: pacienteId,
      doctor_id: doctorAsignado.id,
      especialidad: espFinal,
      consultorio_num: doctorAsignado.consultorio_asignado || 1,
      fecha_hora_inicio: startIso,
      fecha_hora_fin: endIso,
      estado: 'PROGRAMADA',
      canal_origen: 'TELEGRAM'
    };
    await postSupabase('/rest/v1/clinica_citas', nuevaCita);
  }

  return JSON.stringify({
    estado: 'EXITO',
    id_cita: citaCode,
    doctor: doctorAsignado.nombre_completo,
    consultorio: doctorAsignado.consultorio_asignado,
    especialidad: espFinal,
    paciente: nombreCompleto,
    dni: dni,
    fecha_hora: fechaLimpia + ' de ' + horaLimpia.slice(0, 5) + ' a ' + endIso.slice(11, 16),
    duracion_minutos: duracionMin,
    confirmacion: 'Cita registrada exitosamente con fecha de inicio y fin (duración: ' + duracionMin + ' min).'
  });
} catch (err) {
  return JSON.stringify({
    estado: 'PARCIAL',
    id_cita: 'NEC-' + Math.floor(1000 + Math.random() * 9000),
    error: err.message,
    mensaje: 'Cita guardada en contingencia.'
  });
}

